/* A base inicial é incorporada ao final deste arquivo para funcionar via file://.
   CSVs selecionados são lidos localmente pelo Papa Parse, sem upload. */
const COLUNAS = ['id_venda', 'data', 'produto', 'categoria', 'regiao', 'quantidade', 'preco_unitario'];
const moeda = new Intl.NumberFormat('pt-BR', { style: 'currency', currency: 'BRL' });
const numero = new Intl.NumberFormat('pt-BR', { maximumFractionDigits: 2 });
const $ = id => document.getElementById(id);
let dados = [], filtrados = [], dimensao = 'regiao', pagina = 1;
let ordenacao = { chave: 'data', direcao: 1 };
const graficos = {};
const TAMANHO_PAGINA = 20;
// Tema compartilhado dos gráficos: textos azuis e séries em tons de lilás.
if (typeof Chart !== 'undefined') {
  Chart.defaults.color = '#1e40af';
  Object.assign(Chart.defaults.plugins.tooltip, {
    backgroundColor: '#ffffff', titleColor: '#1e40af', bodyColor: '#1e40af',
    borderColor: '#9b72cf', borderWidth: 1
  });
}

function dataValida(valor) {
  if (!/^\d{4}-\d{2}-\d{2}$/.test(valor)) return false;
  const data = new Date(valor + 'T12:00:00Z');
  return Number.isFinite(data.getTime()) && data.toISOString().slice(0, 10) === valor;
}
function lerNumero(valor) {
  const texto = String(valor ?? '').trim();
  // Não convertemos uma célula vazia em zero. Aceitamos decimal com ponto ou vírgula, sem milhar.
  if (!/^[+-]?\d+(?:[.,]\d+)?$/.test(texto)) return null;
  const resultado = Number(texto.replace(',', '.'));
  return Number.isFinite(resultado) ? resultado : null;
}
function validarLinhas(linhas, campos) {
  const local = campos.includes('regiao') ? 'regiao' : campos.includes('canal') ? 'canal' : 'regiao';
  const obrigatorias = ['id_venda', 'data', 'produto', 'categoria', 'quantidade', 'preco_unitario', local];
  const faltantes = obrigatorias.filter(campo => !campos.includes(campo));
  if (faltantes.length) throw new Error('Colunas obrigatórias ausentes: ' + faltantes.join(', '));
  const validas = [], motivos = {};
  let descartadas = 0;
  for (const linha of linhas) {
    const venda = {};
    obrigatorias.forEach(campo => venda[campo] = String(linha[campo] ?? '').trim());
    const problemas = [];
    ['id_venda', 'produto', 'categoria', local].forEach(campo => {
      if (!venda[campo]) problemas.push(campo + ' ausente');
    });
    if (!dataValida(venda.data)) problemas.push('data ausente ou inválida');
    venda.quantidade = lerNumero(linha.quantidade);
    venda.preco_unitario = lerNumero(linha.preco_unitario);
    if (venda.quantidade === null || venda.quantidade < 0 || !Number.isInteger(venda.quantidade)) problemas.push('quantidade ausente ou inválida');
    if (venda.preco_unitario === null || venda.preco_unitario < 0) problemas.push('preço ausente ou inválido');
    const receita = venda.quantidade * venda.preco_unitario;
    if (!problemas.length && (!Number.isFinite(receita) || receita > Number.MAX_SAFE_INTEGER / 100)) problemas.push('faturamento fora do limite numérico');
    if (problemas.length) {
      descartadas++;
      problemas.forEach(motivo => motivos[motivo] = (motivos[motivo] || 0) + 1);
    } else {
      // Centavos inteiros evitam erros de soma comuns com números decimais.
      venda.centavos = Math.round(receita * 100);
      validas.push(venda);
    }
  }
  const soma = validas.reduce((total, venda) => total + venda.centavos, 0);
  if (!Number.isSafeInteger(soma)) throw new Error('Faturamento total acima do limite numérico seguro.');
  return { validas, descartadas, motivos, local };
}
function calcularIndicadores(linhas) {
  const centavos = linhas.reduce((total, venda) => total + venda.centavos, 0);
  const vendas = new Set(linhas.map(venda => venda.id_venda)).size;
  return { faturamento: centavos / 100, vendas, unidades: linhas.reduce((total, venda) => total + venda.quantidade, 0), ticket: vendas ? centavos / 100 / vendas : 0 };
}
function filtrarLinhas(linhas, filtros, local) {
  const busca = filtros.busca.trim().toLocaleLowerCase('pt-BR');
  return linhas.filter(venda => (!filtros.inicio || venda.data >= filtros.inicio)
    && (!filtros.fim || venda.data <= filtros.fim)
    && (!filtros.categoria || venda.categoria === filtros.categoria)
    && (!filtros.local || venda[local] === filtros.local)
    && (!busca || [venda.id_venda, venda.data, venda.produto, venda.categoria, venda[local], venda.quantidade, venda.preco_unitario].join(' ').toLocaleLowerCase('pt-BR').includes(busca)));
}
function preencherOpcoes(id, valores, titulo) {
  $(id).replaceChildren(new Option(titulo, ''));
  [...new Set(valores)].sort((a, b) => a.localeCompare(b, 'pt-BR')).forEach(valor => $(id).add(new Option(valor, valor)));
}
function carregarBase(linhas, campos, titulo, descricao) {
  const resultado = validarLinhas(linhas, campos);
  dados = resultado.validas;
  dimensao = resultado.local;
  $('source-title').textContent = titulo;
  $('source-description').textContent = descricao + (dimensao === 'canal' ? ' Sem região na base: comparação e filtro usam o canal de venda.' : '');
  const repetidos = dados.length - new Set(dados.map(v => v.id_venda)).size;
  $('import-status').textContent = `${numero.format(dados.length)} linhas válidas; ${numero.format(resultado.descartadas)} descartadas.`
    + (resultado.descartadas ? ' Motivos (uma linha pode ter mais de um): ' + Object.entries(resultado.motivos).map(([motivo, total]) => `${motivo}: ${total}`).join('; ') + '.' : '')
    + (repetidos ? ` ${repetidos} linhas com IDs já presentes: mantidas; vendas contam IDs únicos.` : '')
    + (typeof Chart === 'undefined' ? ' Gráficos indisponíveis: conecte-se à internet para carregar Chart.js e recarregue a página.' : '');
  const nome = dimensao === 'regiao' ? 'Região' : 'Canal';
  $('dimension-label').textContent = nome;
  $('dimension-chart-title').textContent = dimensao === 'regiao' ? 'Como as regiões se comparam?' : 'Como os canais se comparam?';
  $('dimension-chart-subtitle').textContent = `Faturamento por ${nome.toLowerCase()} · em reais (R$)`;
  preencherOpcoes('category', dados.map(v => v.categoria), 'Todas as categorias');
  preencherOpcoes('dimension', dados.map(v => v[dimensao]), dimensao === 'regiao' ? 'Todas as regiões' : 'Todos os canais');
  $('february-year').replaceChildren();
  [...new Set(dados.map(venda => venda.data.slice(0, 4)))].sort().reverse().forEach(ano => $('february-year').add(new Option(ano, ano)));
  limparFiltros();
}
function limparFiltros() {
  ['start-date', 'end-date', 'category', 'dimension', 'search'].forEach(id => $(id).value = '');
  ordenacao = { chave: 'data', direcao: 1 };
  $('february-year').selectedIndex = 0;
  atualizar();
}
function atualizar() {
  pagina = 1;
  const inicio = $('start-date').value, fim = $('end-date').value;
  $('end-date').setCustomValidity(inicio && fim && inicio > fim ? 'A data final deve ser igual ou posterior à inicial.' : '');
  filtrados = filtrarLinhas(dados, { inicio, fim, categoria: $('category').value, local: $('dimension').value, busca: $('search').value }, dimensao);
  const indicadores = calcularIndicadores(filtrados);
  $('revenue').textContent = moeda.format(indicadores.faturamento);
  $('sales').textContent = numero.format(indicadores.vendas);
  $('units').textContent = numero.format(indicadores.unidades);
  $('ticket').textContent = moeda.format(indicadores.ticket);
  $('record-count').textContent = `${numero.format(filtrados.length)} de ${numero.format(dados.length)} registros`;
  $('empty-message').hidden = filtrados.length > 0;
  $('export-button').disabled = !filtrados.length;
  atualizarGraficos();
  atualizarTabela();
}
function agrupar(linhas, chave) {
  const grupos = new Map();
  linhas.forEach(venda => { const nome = chave === 'mes' ? venda.data.slice(0, 7) : venda[chave]; grupos.set(nome, (grupos.get(nome) || 0) + venda.centavos); });
  return [...grupos].map(([nome, centavos]) => [nome, centavos / 100]);
}
function serieMensal(linhas) {
  if (!linhas.length) return [];
  const grupos = new Map(agrupar(linhas, 'mes'));
  const meses = [...grupos.keys()].sort();
  let [ano, mes] = meses[0].split('-').map(Number);
  const resultado = [];
  // Inclui meses sem vendas entre o primeiro e o último mês dos registros filtrados.
  while (`${ano}-${String(mes).padStart(2, '0')}` <= meses.at(-1)) {
    const chave = `${ano}-${String(mes).padStart(2, '0')}`;
    resultado.push([chave, grupos.get(chave) || 0]);
    mes++; if (mes > 12) { mes = 1; ano++; }
  }
  return resultado;
}
// A cor depende do nome na base completa: filtros e ordenação não trocam as cores.
function coresDasBarras(id, serie) {
  const paleta = ['#9b72cf', '#b59ade', '#7c53b5', '#c4afe7', '#8e63c4', '#d4c2ef', '#aa86d7'];
  const campo = id === 'category-chart' ? 'categoria' : dimensao;
  const nomes = [...new Set(dados.map(venda => venda[campo]))].sort((a, b) => a.localeCompare(b, 'pt-BR'));
  const cores = new Map(nomes.map((nome, indice) => [nome, paleta[indice % paleta.length]]));
  return serie.map(([nome]) => cores.get(nome));
}
function desenharGrafico(id, tipo, serie, cor, horizontal = false) {
  if (typeof Chart === 'undefined') return;
  const labels = serie.map(([nome]) => tipo === 'line' ? new Date(nome + '-01T12:00:00Z').toLocaleDateString('pt-BR', { month: 'short', year: '2-digit', timeZone: 'UTC' }) : nome);
  const valores = serie.map(([, valor]) => valor);
  const cores = tipo === 'line' ? '#9b72cf26' : coresDasBarras(id, serie);
  if (graficos[id]) { graficos[id].data.labels = labels; graficos[id].data.datasets[0].data = valores; graficos[id].data.datasets[0].backgroundColor = cores; graficos[id].update(); return; }
  graficos[id] = new Chart($(id), {
    type: tipo,
    data: { labels, datasets: [{ label: 'Faturamento (R$)', data: valores, borderColor: cor, backgroundColor: cores, fill: tipo === 'line', tension: .25, borderRadius: 5, borderWidth: tipo === 'line' ? 2 : 0, pointRadius: 3, maxBarThickness: 38 }] },
    options: { responsive: true, maintainAspectRatio: false, indexAxis: horizontal ? 'y' : 'x', plugins: { legend: { display: true, labels: { boxWidth: 12 } }, tooltip: { callbacks: { label: context => 'Faturamento: ' + moeda.format(horizontal ? context.parsed.x : context.parsed.y) } } }, scales: { [horizontal ? 'x' : 'y']: { beginAtZero: true, title: { display: true, text: 'Faturamento (R$)' }, ticks: { callback: valor => 'R$ ' + numero.format(valor) } }, [horizontal ? 'y' : 'x']: { grid: { display: false }, title: { display: true, text: tipo === 'line' ? 'Mês / ano' : id === 'category-chart' ? 'Categoria' : 'Região / canal' } } } }
  });
}
function atualizarGraficos() {
  desenharGrafico('monthly-chart', 'line', serieMensal(filtrados), '#9b72cf');
  desenharGrafico('category-chart', 'bar', agrupar(filtrados, 'categoria').sort((a, b) => b[1] - a[1]), '#9b72cf', true);
  desenharGrafico('dimension-chart', 'bar', agrupar(filtrados, dimensao).sort((a, b) => b[1] - a[1]), '#9b72cf', true);
  atualizarPizza();
  atualizarGraficosProdutos();
  atualizarMapaCalor();
  atualizarRankingFevereiro();
}
function rankingFevereiro(linhas, ano) {
  const fevereiro = linhas.filter(venda => venda.data.slice(0, 7) === `${ano}-02`);
  const produtos = unidadesPorProduto(fevereiro);
  const compararNome = (a, b) => a[0].localeCompare(b[0], 'pt-BR');
  return {
    mais: [...produtos].sort((a, b) => b[1] - a[1] || compararNome(a, b)).slice(0, 5),
    menos: [...produtos].sort((a, b) => a[1] - b[1] || compararNome(a, b)).slice(0, 5)
  };
}
function atualizarRankingFevereiro() {
  const ano = $('february-year').value;
  const ranking = rankingFevereiro(filtrados, ano);
  const mensagem = ranking.mais.length ? `Fevereiro de ${ano} · empates ordenados pelo nome do produto.` : ano ? `Nenhum registro em fevereiro de ${ano} corresponde aos filtros. Use a demonstração ou importe uma base com vendas nesse mês.` : 'Nenhum ano disponível na base atual.';
  $('february-most-note').textContent = mensagem;
  $('february-least-note').textContent = mensagem;
  desenharGraficoProduto('february-most-chart', 'bar', ranking.mais, 'Unidades vendidas', 'Produto');
  desenharGraficoProduto('february-least-chart', 'bar', ranking.menos, 'Unidades vendidas', 'Produto');
}
function dadosMapaCalor(linhas, local) {
  if (local !== 'regiao') return null;
  const bebidas = linhas.filter(venda => normalizarTexto(venda.regiao) === 'nordeste' && ['bebida', 'bebidas'].includes(normalizarTexto(venda.categoria)));
  const meses = serieMensal(linhas).map(([mes]) => mes);
  const produtos = [...new Set(bebidas.map(venda => venda.produto))].sort((a, b) => a.localeCompare(b, 'pt-BR'));
  const grupos = new Map();
  bebidas.forEach(venda => {
    const chave = JSON.stringify([venda.produto, venda.data.slice(0, 7)]);
    const celula = grupos.get(chave) || { unidades: 0, registros: 0 };
    celula.unidades += venda.quantidade;
    celula.registros++;
    grupos.set(chave, celula);
  });
  const matriz = produtos.map(produto => meses.map(mes => grupos.get(JSON.stringify([produto, mes])) || null));
  const maximo = [...grupos.values()].reduce((maior, celula) => Math.max(maior, celula.unidades), 0);
  return { meses, produtos, matriz, maximo };
}
function atualizarMapaCalor() {
  const mapa = dadosMapaCalor(filtrados, dimensao);
  $('heatmap-head').replaceChildren();
  $('heatmap-body').replaceChildren();
  const vazio = !mapa || !mapa.produtos.length;
  $('heatmap-content').hidden = vazio;
  $('heatmap-legend').hidden = vazio;
  $('heatmap-note').textContent = !mapa ? 'Esta base não possui região. Importe um CSV com regiao para analisar o Nordeste.' : vazio ? 'Nenhuma venda de bebida no Nordeste corresponde aos filtros.' : '';
  if (vazio) return;
  $('heatmap-maximum').textContent = `Mais unidades (${numero.format(mapa.maximo)})`;
  const cabecalho = document.createElement('tr');
  const titulo = document.createElement('th'); titulo.scope = 'col'; titulo.textContent = 'Produto / mês'; cabecalho.append(titulo);
  mapa.meses.forEach(mes => { const th = document.createElement('th'); th.scope = 'col'; th.textContent = mes.split('-').reverse().join('/'); cabecalho.append(th); });
  $('heatmap-head').append(cabecalho);
  const cores = ['#faf5ff', '#ede9fe', '#ddd6fe', '#c4b5fd', '#b7a0ed'];
  mapa.produtos.forEach((produto, linha) => {
    const tr = document.createElement('tr');
    const th = document.createElement('th'); th.scope = 'row'; th.textContent = produto; tr.append(th);
    mapa.matriz[linha].forEach((celula, coluna) => {
      const td = document.createElement('td');
      td.textContent = celula ? numero.format(celula.unidades) : '—';
      td.title = `${produto} · ${mapa.meses[coluna]}: ${celula ? `${numero.format(celula.unidades)} unidades em ${numero.format(celula.registros)} registros` : 'sem registros'}`;
      if (celula) {
        const nivel = mapa.maximo && celula.unidades > 0 ? Math.min(4, Math.ceil(celula.unidades / mapa.maximo * 5) - 1) : 0;
        td.style.backgroundColor = cores[nivel];
        td.style.color = '#1e40af';
      } else td.className = 'heatmap-missing';
      tr.append(td);
    });
    $('heatmap-body').append(tr);
  });
}
function normalizarTexto(texto) {
  return String(texto).normalize('NFD').replace(/[\u0300-\u036f]/g, '').trim().toLowerCase();
}
function ehHamburguer(venda) {
  return ['lanche', 'lanches', 'hamburguer', 'hamburgueres'].includes(normalizarTexto(venda.categoria));
}
function inicioDaSemana(data) {
  const dia = new Date(data + 'T12:00:00Z');
  dia.setUTCDate(dia.getUTCDate() - (dia.getUTCDay() + 6) % 7);
  return dia.toISOString().slice(0, 10);
}
function vendasPorSemana(linhas) {
  const grupos = new Map();
  linhas.forEach(venda => {
    const semana = inicioDaSemana(venda.data);
    if (!grupos.has(semana)) grupos.set(semana, new Set());
    grupos.get(semana).add(venda.id_venda);
  });
  const semanas = [...grupos.keys()].sort();
  if (!semanas.length) return [];
  const resultado = [], dia = new Date(semanas[0] + 'T12:00:00Z');
  while (dia.toISOString().slice(0, 10) <= semanas.at(-1)) {
    const semana = dia.toISOString().slice(0, 10);
    resultado.push([semana, grupos.get(semana)?.size || 0]);
    dia.setUTCDate(dia.getUTCDate() + 7);
  }
  return resultado;
}
function unidadesPorProduto(linhas) {
  const grupos = new Map();
  linhas.forEach(venda => grupos.set(venda.produto, (grupos.get(venda.produto) || 0) + venda.quantidade));
  return [...grupos].sort((a, b) => b[1] - a[1]);
}
function seriesProdutos(linhas, local) {
  const hamburgueres = linhas.filter(ehHamburguer);
  // Uma base com apenas canal não permite inferir a região dos registros.
  const nordeste = local === 'regiao' ? linhas.filter(venda => normalizarTexto(venda.regiao) === 'nordeste') : [];
  return {
    semanal: vendasPorSemana(hamburgueres), mensal: serieMensal(hamburgueres),
    hamburguerNordeste: unidadesPorProduto(nordeste.filter(ehHamburguer)),
    bebidaNordeste: unidadesPorProduto(nordeste.filter(venda => ['bebida', 'bebidas'].includes(normalizarTexto(venda.categoria))))
  };
}
function desenharGraficoProduto(id, tipo, serie, unidade, eixo) {
  if (typeof Chart === 'undefined') return;
  const labels = serie.map(([nome]) => eixo === 'Semana' ? nome.split('-').reverse().join('/') : eixo === 'Mês' ? nome.split('-').reverse().join('/') : nome);
  const valores = serie.map(([, valor]) => valor);
  const pizza = tipo === 'pie';
  const paleta = ['#9b72cf', '#b59ade', '#7c53b5', '#c4afe7', '#8e63c4', '#d4c2ef', '#aa86d7'];
  const produtos = [...new Set(dados.map(venda => venda.produto))].sort((a, b) => a.localeCompare(b, 'pt-BR'));
  const cores = pizza ? serie.map(([nome]) => paleta[produtos.indexOf(nome) % paleta.length]) : '#9b72cf';
  if (graficos[id]) {
    graficos[id].data.labels = labels;
    graficos[id].data.datasets[0].data = valores;
    graficos[id].data.datasets[0].backgroundColor = cores;
    graficos[id].update();
    return;
  }
  const formatar = valor => unidade === 'Faturamento (R$)' ? moeda.format(valor) : numero.format(valor);
  const corTexto = '#1e40af';
  const options = {
    responsive: true, maintainAspectRatio: false,
    plugins: {
      legend: { display: true, ...(pizza ? { position: 'bottom', onClick: () => {} } : {}), labels: { boxWidth: 12, color: corTexto } },
      tooltip: { backgroundColor: '#ffffff', titleColor: corTexto, bodyColor: corTexto, borderColor: '#9b72cf', borderWidth: 1, callbacks: { label: contexto => {
        const valor = pizza ? contexto.parsed : contexto.parsed.y;
        const total = contexto.dataset.data.reduce((soma, item) => soma + item, 0);
        return `${pizza ? contexto.label : unidade}: ${formatar(valor)}${pizza ? ` unidades (${numero.format(total ? valor / total * 100 : 0)}%)` : ''}`;
      } } }
    }
  };
  if (!pizza) options.scales = {
    x: { title: { display: true, text: eixo, color: corTexto }, ticks: { color: corTexto }, grid: { display: false } },
    y: { beginAtZero: true, title: { display: true, text: unidade, color: corTexto }, ticks: { color: corTexto, ...(unidade === 'Faturamento (R$)' ? {} : { precision: 0 }), callback: formatar } }
  };
  graficos[id] = new Chart($(id), {
    type: tipo, data: { labels, datasets: [{ label: unidade, data: valores, backgroundColor: cores, borderColor: pizza ? '#ffffff' : '#9b72cf', borderWidth: 2, tension: .2, maxBarThickness: 38 }] }, options
  });
}
function atualizarGraficosProdutos() {
  const series = seriesProdutos(filtrados, dimensao);
  $('burger-weekly-note').textContent = series.semanal.length ? '' : 'Nenhuma venda de hambúrguer corresponde aos filtros.';
  $('burger-monthly-note').textContent = series.mensal.length ? '' : 'Nenhuma venda de hambúrguer corresponde aos filtros.';
  const semRegiao = 'Esta base não possui região. Importe um CSV com regiao para analisar o Nordeste.';
  $('burger-northeast-note').textContent = dimensao !== 'regiao' ? semRegiao : series.hamburguerNordeste.length ? '' : 'Nenhuma venda de hambúrguer no Nordeste corresponde aos filtros.';
  $('drink-northeast-note').textContent = dimensao !== 'regiao' ? semRegiao : series.bebidaNordeste.some(([, unidades]) => unidades > 0) ? '' : 'Nenhuma unidade de bebida no Nordeste corresponde aos filtros.';
  desenharGraficoProduto('burger-weekly-chart', 'line', series.semanal, 'Vendas únicas', 'Semana');
  desenharGraficoProduto('burger-monthly-chart', 'line', series.mensal, 'Faturamento (R$)', 'Mês');
  desenharGraficoProduto('burger-northeast-chart', 'bar', series.hamburguerNordeste, 'Unidades vendidas', 'Produto');
  desenharGraficoProduto('drink-northeast-chart', 'pie', series.bebidaNordeste, 'Unidades vendidas', 'Produto');
}
function atualizarPizza() {
  const serie = agrupar(filtrados, 'categoria').sort((a, b) => b[1] - a[1]);
  const valores = serie.map(([, valor]) => valor);
  const total = valores.reduce((soma, valor) => soma + valor, 0);
  $('pie-empty').hidden = total > 0;
  if (typeof Chart === 'undefined') return;
  const labels = serie.map(([nome]) => nome);
  const tonsLilas = ['#9b72cf', '#b59ade', '#7c53b5', '#c4afe7', '#8e63c4', '#d4c2ef', '#aa86d7'];
  const categorias = [...new Set(dados.map(venda => venda.categoria))].sort((a, b) => a.localeCompare(b, 'pt-BR'));
  const coresPorCategoria = new Map(categorias.map((nome, indice) => [nome, tonsLilas[indice % tonsLilas.length]]));
  const cores = serie.map(([nome]) => coresPorCategoria.get(nome));
  if (graficos.pizza) {
    graficos.pizza.data.labels = labels;
    graficos.pizza.data.datasets[0].data = valores;
    graficos.pizza.data.datasets[0].backgroundColor = cores;
    graficos.pizza.update();
    return;
  }
  graficos.pizza = new Chart($('category-pie-chart'), {
    type: 'pie',
    data: { labels, datasets: [{ label: 'Faturamento (R$)', data: valores, backgroundColor: cores, borderColor: '#ffffff', borderWidth: 2 }] },
    options: {
      responsive: true, maintainAspectRatio: false,
      plugins: {
        // A legenda identifica as cores; o recorte dos dados é controlado pelos filtros.
        legend: { position: 'bottom', onClick: () => {}, labels: { boxWidth: 12, padding: 16 } },
        tooltip: { callbacks: { label: contexto => {
          const soma = contexto.dataset.data.reduce((acumulado, valor) => acumulado + valor, 0);
          const percentual = soma > 0 ? contexto.parsed / soma * 100 : 0;
          return `${contexto.label}: ${moeda.format(contexto.parsed)} (${numero.format(percentual)}%)`;
        } } }
      }
    }
  });
}
function linhasOrdenadas() {
  return [...filtrados].sort((a, b) => {
    const x = a[ordenacao.chave], y = b[ordenacao.chave];
    return ordenacao.direcao * (typeof x === 'number' ? x - y : String(x).localeCompare(String(y), 'pt-BR', { numeric: true }));
  });
}
function atualizarTabela() {
  const colunas = [['id_venda', 'ID'], ['data', 'Data'], ['produto', 'Produto'], ['categoria', 'Categoria'], [dimensao, dimensao === 'regiao' ? 'Região' : 'Canal'], ['quantidade', 'Unidades'], ['preco_unitario', 'Preço unitário'], ['centavos', 'Faturamento']];
  $('table-head').replaceChildren();
  colunas.forEach(([chave, nome]) => {
    const th = document.createElement('th'), botao = document.createElement('button');
    th.scope = 'col';
    if (ordenacao.chave === chave) th.setAttribute('aria-sort', ordenacao.direcao === 1 ? 'ascending' : 'descending');
    botao.textContent = nome + (ordenacao.chave === chave ? ordenacao.direcao === 1 ? ' ↑' : ' ↓' : ' ↕');
    botao.addEventListener('click', () => { ordenacao = { chave, direcao: ordenacao.chave === chave ? -ordenacao.direcao : 1 }; pagina = 1; atualizarTabela(); });
    if (['quantidade', 'preco_unitario', 'centavos'].includes(chave)) th.className = 'numeric';
    th.append(botao); $('table-head').append(th);
  });
  $('table-body').replaceChildren();
  const ordenadas = linhasOrdenadas();
  ordenadas.slice((pagina - 1) * TAMANHO_PAGINA, pagina * TAMANHO_PAGINA).forEach(venda => {
    const tr = document.createElement('tr');
    colunas.forEach(([chave]) => {
      const td = document.createElement('td');
      td.textContent = chave === 'centavos' ? moeda.format(venda.centavos / 100) : chave === 'preco_unitario' ? moeda.format(venda[chave]) : chave === 'data' ? venda.data.split('-').reverse().join('/') : String(venda[chave]);
      if (['quantidade', 'preco_unitario', 'centavos'].includes(chave)) td.className = 'numeric';
      tr.append(td);
    });
    $('table-body').append(tr);
  });
  if (!ordenadas.length) { const tr = document.createElement('tr'), td = document.createElement('td'); td.colSpan = colunas.length; td.textContent = 'Nenhum registro encontrado.'; tr.append(td); $('table-body').append(tr); }
  const paginas = Math.max(1, Math.ceil(ordenadas.length / TAMANHO_PAGINA));
  $('page-info').textContent = `Página ${pagina} de ${paginas} · até ${TAMANHO_PAGINA} registros por página`;
  $('previous-page').disabled = pagina === 1;
  $('next-page').disabled = pagina >= paginas;
}
function importarCSV(arquivo) {
  if (!arquivo) return;
  if (typeof Papa === 'undefined') { $('import-status').textContent = 'Importação indisponível. Conecte-se à internet para carregar Papa Parse e recarregue a página.'; return; }
  Papa.parse(arquivo, { header: true, skipEmptyLines: 'greedy', transformHeader: campo => campo.replace(/^\uFEFF/, '').trim().toLowerCase(), complete: resultado => {
    try {
      if (resultado.errors.length) throw new Error('CSV malformado: ' + resultado.errors.slice(0, 3).map(erro => `${erro.message}${erro.row !== undefined ? ' (registro ' + (erro.row + 1) + ')' : ''}`).join('; ') + '. Corrija a estrutura e tente novamente.');
      carregarBase(resultado.data, resultado.meta.fields || [], 'Base importada · ' + arquivo.name, 'Arquivo processado localmente no navegador.');
    } catch (erro) { $('import-status').textContent = erro.message + ' A base anterior foi mantida.'; }
    $('csv-file').value = '';
  }, error: erro => { $('import-status').textContent = 'Não foi possível ler o arquivo: ' + erro.message; $('csv-file').value = ''; } });
}
function criarCSV(linhas) {
  const campos = ['id_venda', 'data', 'produto', 'categoria', dimensao, 'quantidade', 'preco_unitario'];
  return Papa.unparse(linhas.map(venda => Object.fromEntries(campos.map(campo => [campo, venda[campo]]))), { columns: campos, escapeFormulae: true, newline: '\r\n' });
}
function exportarCSV() {
  if (typeof Papa === 'undefined') { $('import-status').textContent = 'Conecte-se à internet e recarregue a página para habilitar a exportação.'; return; }
  const url = URL.createObjectURL(new Blob(['\uFEFF', criarCSV(linhasOrdenadas())], { type: 'text/csv;charset=utf-8;' }));
  const link = document.createElement('a'); link.href = url; link.download = 'vendas-filtradas.csv'; link.click();
  setTimeout(() => URL.revokeObjectURL(url), 1000);
}
function iniciar() {
  $('february-year').addEventListener('change', atualizarRankingFevereiro);
  ['start-date', 'end-date', 'category', 'dimension'].forEach(id => $(id).addEventListener('change', atualizar));
  $('search').addEventListener('input', atualizar);
  $('clear-button').addEventListener('click', limparFiltros);
  $('csv-file').addEventListener('change', evento => importarCSV(evento.target.files[0]));
  $('export-button').addEventListener('click', exportarCSV);
  $('previous-page').addEventListener('click', () => { pagina--; atualizarTabela(); });
  $('next-page').addEventListener('click', () => { pagina++; atualizarTabela(); });
  $('demo-button').addEventListener('click', () => carregarBase(DADOS_EXEMPLO, COLUNAS, 'Dados demonstrativos · base fictícia', '200 registros de janeiro a dezembro de 2025. Valores criados apenas para a atividade.'));
  $('original-button').addEventListener('click', () => carregarBase(DADOS_HAMBURGUERIA, CAMPOS_HAMBURGUERIA, 'Base fornecida · vendas_hamburgueria.csv', '1.367 registros de julho a setembro de 2026. Origem e veracidade não auditadas.'));
  $('demo-button').click();
}
